/*
 * Скетч для проверки светодиодов на плате ESP32-S3
 * 
 * 1. Мигает обычным светодиодом (если он есть).
 * 2. Перебирает цвета на встроенном RGB-светодиоде (WS2812).
 * 
 * Перед загрузкой настройте константы LED_PIN и RGB_PIN под вашу плату!
 */

// --- НАСТРОЙКИ ПИНОВ (ИЗМЕНИТЕ ПРИ НЕОБХОДИМОСТИ) ---
// Пин для обычного светодиода. Если его нет, установите значение -1.
// Примеры: 21 для XIAO ESP32-S3, 13 для некоторых плат Adafruit.
#define LED_PIN 21 

// Пин для RGB-светодиода (WS2812). Если его нет, установите значение -1.
// Примеры: 48 для DevKitC-1, 38 для Waveshare, 21 для XIAO ESP32-S3.
#define RGB_PIN 48 

// Количество светодиодов в цепочке (для платы обычно 1)
#define NUM_LEDS 1
// -----------------------------------------------------

// Подключаем библиотеку для работы с RGB-светодиодами
#include <Adafruit_NeoPixel.h>

// Создаём объект для управления RGB-светодиодом
Adafruit_NeoPixel pixels(NUM_LEDS, RGB_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  Serial.begin(115200);
  delay(1000); // Даём время на инициализацию Serial
  Serial.println("\n--- Начало проверки светодиодов ESP32-S3 ---");

  // Настройка обычного светодиода
  if (LED_PIN >= 0) {
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);
    Serial.printf("Обычный светодиод инициализирован на пине %d\n", LED_PIN);
  } else {
    Serial.println("Обычный светодиод не используется.");
  }

  // Настройка RGB-светодиода
  if (RGB_PIN >= 0) {
    pixels.begin();
    pixels.clear();
    pixels.show();
    Serial.printf("RGB-светодиод инициализирован на пине %d\n", RGB_PIN);
  } else {
    Serial.println("RGB-светодиод не используется.");
  }

  Serial.println("--- Инициализация завершена ---\n");
}

void loop() {
  // --- Проверка обычного светодиода ---
  if (LED_PIN >= 0) {
    Serial.println("Мигание обычным светодиодом...");
    digitalWrite(LED_PIN, HIGH);
    delay(500);
    digitalWrite(LED_PIN, LOW);
    delay(500);
  }

  // --- Проверка RGB-светодиода ---
  if (RGB_PIN >= 0) {
    Serial.println("Перебор цветов RGB-светодиода...");

    // Красный
    Serial.println("Красный");
    pixels.setPixelColor(0, pixels.Color(255, 0, 0));
    pixels.show();
    delay(1000);

    // Зелёный
    Serial.println("Зелёный");
    pixels.setPixelColor(0, pixels.Color(0, 255, 0));
    pixels.show();
    delay(1000);

    // Синий
    Serial.println("Синий");
    pixels.setPixelColor(0, pixels.Color(0, 0, 255));
    pixels.show();
    delay(1000);

    // Белый (смешение всех цветов)
    Serial.println("Белый");
    pixels.setPixelColor(0, pixels.Color(255, 255, 255));
    pixels.show();
    delay(1000);

    // Выключение
    Serial.println("Выключен");
    pixels.clear();
    pixels.show();
    delay(1000);
  }
}
